import json

todos = [
    {"id": "1", "title": "完成報告", "completed": False},
    {"id": "2", "title": "準備會議資料", "completed": True}
]

todo_id_counter = 3

def handle(method, path, body):
    global todos, todo_id_counter

    if method == "GET" and path == "/todos":
        return (200, {"items": todos})

    elif method == "POST" and path == "/todos":
        data = json.loads(body)
        new_todo = {
            "id": str(todo_id_counter),
            "title": data["title"],
            "completed": False
        }
        todos.append(new_todo)
        todo_id_counter += 1
        return (200, new_todo)

    elif method == "PUT" and path.startswith("/todos/"):
        todo_id = path.split("/")[3]
        data = json.loads(body)
        for todo in todos:
            if todo["id"] == todo_id:
                todo["completed"] = data["completed"]
                return (200, todo)
        return (404, {"error": "待辦事項未找到"})

    elif method == "DELETE" and path.startswith("/todos/"):
        todo_id = path.split("/")[3]
        for i, todo in enumerate(todos):
            if todo["id"] == todo_id:
                todos.pop(i)
                return (200, {"message": "待辦事項已刪除"})
        return (404, {"error": "待辦事項未找到"})

    elif method == "GET" and path == "/todos/count":
        count = len([todo for todo in todos if not todo["completed"]])
        return (200, {"count": count})

    return (404, {"error": "未找到路由"})

