document.addEventListener('DOMContentLoaded', () => {
    const todoInput = document.getElementById('todoInput');
    const addBtn = document.getElementById('addBtn');
    const todoList = document.getElementById('todoList');
    const countDisplay = document.getElementById('countDisplay');

    // 從API取得待辦事項列表並更新UI
    async function loadTodos() {
        try {
            const response = await fetch('api/todos');
            const todos = await response.json();
            updateTodoList(todos);
            updateCountDisplay(todos);
        } catch (error) {
            console.error('載入待辦事項失敗:', error);
        }
    }

    // 更新待辦列表顯示
    function updateTodoList(todos) {
        todoList.innerHTML = '';
        todos.items.forEach(todo => {
            const li = document.createElement('li');
            li.className = 'todo-item';
            li.dataset.id = todo.id;

            li.innerHTML = `
                <span class="todo-text ${todo.completed ? 'completed' : ''}">
                    ${todo.title}
                </span>
                <div class="todo-actions">
                    <button class="toggle-btn" data-action="toggle" data-id="${todo.id}">
                        ${todo.completed ? '取消完成' : '標記完成'}
                    </button>
                    <button class="delete-btn" data-action="delete" data-id="${todo.id}">刪除</button>
                </div>
            `;

            todoList.appendChild(li);
        });
    }

    // 更新未完成數量顯示
    function updateCountDisplay(todos) {
        const count = todos.items.filter(todo => !todo.completed).length;
        countDisplay.textContent = `尚未完成的待辦事項：${count}`;
    }

    // 新增待辦事項
    async function addTodo() {
        const title = todoInput.value.trim();
        if (!title) return;

        try {
            const response = await fetch('api/todos', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ title })
            });

            if (response.ok) {
                todoInput.value = '';
                await loadTodos();
            } else {
                console.error('新增待辦事項失敗');
            }
        } catch (error) {
            console.error('新增待辦事項時發生錯誤:', error);
        }
    }

    // 切換待辦事項完成狀態
    async function toggleTodo(id) {
        try {
            const response = await fetch(`api/todos/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ completed: true })
            });

            if (response.ok) {
                await loadTodos();
            } else {
                console.error('更新待辦事項狀態失敗');
            }
        } catch (error) {
            console.error('更新待辦事項狀態時發生錯誤:', error);
        }
    }

    // 刪除待辦事項
    async function deleteTodo(id) {
        try {
            const response = await fetch(`api/todos/${id}`, {
                method: 'DELETE'
            });

            if (response.ok) {
                await loadTodos();
            } else {
                console.error('刪除待辦事項失敗');
            }
        } catch (error) {
            console.error('刪除待辦事項時發生錯誤:', error);
        }
    }

    // 綁定事件處理器
    addBtn.addEventListener('click', addTodo);

    todoInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') addTodo();
    });

    todoList.addEventListener('click', (e) => {
        const action = e.target.dataset.action;
        const id = e.target.dataset.id;

        if (action === 'toggle') {
            toggleTodo(id);
        } else if (action === 'delete') {
            deleteTodo(id);
        }
    });

    // 初始化載入待辦事項
    loadTodos();
});

